using System;
using System.Collections.Generic;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "AllPlayerDicesList", menuName = "Data/Battle/Dice System/AllPlayerDicesList")]
public class AllPlayerDicesList : DicesList
{
	[SerializeField]
	private DiceTier debugTier;

	[NonSerialized]
	public List<Dice> DiceMods = new List<Dice>();

	public override Dice GetDice(string name)
	{
		name = ReplaceDiceNameTransformed(name);
		for (int i = 0; i < DiceMods.Count; i++)
		{
			if (name == DiceMods[i].name.ToLower().Replace(" ", ""))
			{
				return DiceMods[i];
			}
		}
		return base.GetDice(name);
	}

	public int GetAllPlayerDiceDiscoveredTotal()
	{
		List<Dice> list = dice.Duplicate();
		list.RemoveAll(delegate(Dice die)
		{
			PlayerDice playerDice = die as PlayerDice;
			return playerDice.CompendiumItemState == CompendiumItemState.Undiscovered || playerDice.CompendiumItemState == CompendiumItemState.Locked || playerDice.DiceTier == debugTier || playerDice.Tutorial;
		});
		return list.Count;
	}

	public int GetAllPlayerDiceTotalWithoutTutorialAndDebug()
	{
		List<Dice> list = dice.Duplicate();
		list.RemoveAll(delegate(Dice die)
		{
			PlayerDice playerDice = die as PlayerDice;
			return playerDice.DiceTier == debugTier || playerDice.Tutorial;
		});
		return list.Count;
	}

	public int GetAllPlayerDiceDiscoveredFromCharacterTotal(Character character)
	{
		List<Dice> list = dice.Duplicate();
		list.RemoveAll(delegate(Dice die)
		{
			PlayerDice playerDice = die as PlayerDice;
			return playerDice.CompendiumItemState == CompendiumItemState.Undiscovered || playerDice.CompendiumItemState == CompendiumItemState.Locked || playerDice.DiceTier == debugTier || playerDice.Tutorial || playerDice.Character != character;
		});
		return list.Count;
	}

	public int GetAllPlayerDiceFromCharacterTotalWithoutTutorialAndDebug(Character character)
	{
		List<Dice> list = dice.Duplicate();
		list.RemoveAll(delegate(Dice die)
		{
			PlayerDice playerDice = die as PlayerDice;
			return playerDice.DiceTier == debugTier || playerDice.Tutorial || playerDice.Character != character;
		});
		return list.Count;
	}
}
